class UpdateClusterRequestAutoscalerConfig(ScalewayModel):
    scale_down_disabled: bool | None = None
    """
    Forbid cluster autoscaler to scale down the cluster, defaults to false.
    """
    scale_down_delay_after_add: str | None = None
    """
    How long after scale up the scale down evaluation resumes.
    """
