    """
    Kubernetes autoscaler strategy to fit pods into nodes, see
    https://github.com/kubernetes/autoscaler/blob/master/cluster-autoscaler/FAQ.md#what-
    are-expanders for details.
    """
    ignore_daemonsets_utilization: bool | None = None
    """
    Ignore DaemonSet pods when calculating resource utilization for scaling down,
    defaults to false.
    """
    balance_similar_node_groups: bool | None = None
    """
    Detect similar node groups and balance the number of nodes between them, defaults to
    false.
    """
    expendable_pods_priority_cutoff: int | None = None
    """
    Pods with priority below cutoff will be expendable. They can be killed without any
    consideration during scale down and they won't cause scale up. Pods with null
    priority (PodPriority disabled) are non expendable.
    """
    scale_down_unneeded_time: str | None = None
    """
    How long a node should be unneeded before it is eligible for scale down, defaults to
    10 minutes.
    """
    scale_down_utilization_threshold: FloatValue | None = None
    """
    Node utilization level, defined as a sum of requested resources divided by
    allocatable capacity, below which a node can be considered for scale down.
    """
    max_graceful_termination_sec: int | None = None
    """
    Maximum number of seconds the cluster autoscaler waits for pod termination when
    trying to scale down a node, defaults to 600 (10 minutes).
    """
    skip_nodes_with_local_storage: bool | None = None
    """
    Cluster autoscaler will never delete nodes with pods with local storage, e.g.
    EmptyDir or HostPath, defaults to true.
    """
    log_level: int | None = None
    """
    Cluster autoscaler logging level expressed from 0 to 4 (4 being the more verbose),
    defaults to 2. see https://github.com/kubernetes/autoscaler/blob/master/cluster-
    autoscaler/FAQ.md#how-can-i-increase-the-information-that-the-ca-is-logging for
    details.
    """


